INSERT INTO squad_positions VALUES(21,'AVL','가르나초','W','OWNED','88210X4101720004100011000',7.030000000000000248,'r6','최근 6경기 평균 7.03 (첼시 25/26 실측)','w_winger','Versatile',0.936000000000000054,'transfer_targets 실측 이관(첼시 25/26) | 재산출 2026-08-06 (fc26-heatmap.html ROLE_VARIANTS 파싱, 역할 수 37 확인)','OWNED — 첼시에서 임대+조건부 의무매입(출전 수 연동, Ornstein 1티어). 실측 표본이 첼시 시절이라 에메리 체제 데이터가 아님. 로저스(→첼시 £117m) 이탈로 비어 있던 LW 슬롯을 메운다. | [2026-08-06 교정] obs#94(가르나초 insidefwd→winger 교체)가 WM 행에만 적용되고 W 행은 w_insidefwd/Attack + fit_sim 공란으로 남아 있었다. 파이썬으로 툴 decodeMap/placedMap/cmpCos를 재현해 재산출(회귀 게이트 하지무사 .821·은디아예 .825·가르나초 WM .804 전부 재현). W 슬롯 전 8개 조합에서 w_winger/Versatile 0.936이 최고이고 종전 값 w_insidefwd/Attack은 0.601로 **8개 중 최저**였다. x 버킷 15/28 모두 동일 변형을 선택해 값 불변.',26);
INSERT INTO squad_positions VALUES(22,'AVL','가르나초','WM','OWNED','88210X4101720004100011000',7.030000000000000248,'r6','최근 6경기 평균 7.03 (첼시 25/26 실측)','wm_winger','Attack',0.8040000000000000479,'transfer_targets 실측 이관(첼시 25/26)','OWNED — LM 슬롯 커널 적합 wm_insidefwd/Attack 0.911(실측 6경기, 툴중심 22.3/66.5 좌측). 26/27 프리셋 A(가르나초 해방)의 LM 처방 인선. / 🔄 **[2026-07-31 obs#100 — 커널 교체 후 재산출]** 옛 기준(obs#93·#94 이전) 잔존값을 정정했다. 브라우저에서 툴 `placedMap`·`cmpCos`를 직접 호출해 산출(컨텍스트 노트 2), 회귀 게이트 하지무사 .821 재현 확인. 가르나초 LM(x=14): .911 (wm_insidefwd/Attack) → **wm_winger/Attack 0.804**. ⚠️ 옛 값 .911은 슬롯 x를 RM(85)로 잡아도 재현되지 않는다(그 경우 최고 0.110) — 좌측 그리드이므로 정본 x는 LM 14다.',27);
